<?php
require_once '../../../config/sesion.php'; verificarAdmin(); require_once '../../../controllers/LearningController.php'; require_once '../../../includes/learning_helpers.php';
$learning=new LearningController(); $id=(int)($_GET['id']??$_POST['id_logro']??0); $logro=$learning->buscarLogro($id); if(!$logro){header('Location:listar.php');exit;} $cursos=$learning->listarCursosAdmin(); $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verificarCsrfPost();try{$learning->guardarLogro($_POST);header('Location:listar.php?ok=1');exit;}catch(Throwable $e){$error=$e->getMessage();$logro=array_merge($logro,$_POST);}}
?>
<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Editar logro - Learning Lab</title><link rel="stylesheet" href="../../../assets/css/admin.css"></head><body><?php include '../../includes/sidebar.php'; ?><div class="admin-main"><?php include '../../includes/navbar.php'; ?><section class="admin-content learning-admin-page"><div class="gestion-header"><div><span class="learning-admin-kicker">Logros</span><h1>Editar insignia</h1><p class="dashboard-subtitle"><?php echo learningH($logro['nombre']); ?></p></div><a class="btn-limpiar" href="listar.php">Volver</a></div><?php if($error): ?><div class="mensaje-error"><?php echo learningH($error); ?></div><?php endif; ?><form method="POST" class="admin-form learning-form-grid"><?php echo csrfInput(); ?><input type="hidden" name="id_logro" value="<?php echo $id; ?>"><div><label>Nombre</label><input name="nombre" value="<?php echo learningH($logro['nombre']); ?>" required></div><div><label>Código</label><input name="codigo" value="<?php echo learningH($logro['codigo']); ?>" required></div><div class="learning-field-span"><label>Descripción</label><textarea name="descripcion" rows="3" required><?php echo learningH($logro['descripcion']); ?></textarea></div><div><label>Icono</label><input name="icono" value="<?php echo learningH($logro['icono']); ?>"></div><div><label>Criterio</label><select name="criterio"><?php foreach(['primer_curso'=>'Primer curso','cursos_completados'=>'Cantidad de cursos','nota_perfecta'=>'Nota perfecta','curso_especifico'=>'Curso específico'] as $k=>$v): ?><option value="<?php echo $k; ?>" <?php echo $logro['criterio']===$k?'selected':''; ?>><?php echo $v; ?></option><?php endforeach; ?></select></div><div><label>Valor objetivo</label><input type="number" min="1" name="valor_objetivo" value="<?php echo (int)$logro['valor_objetivo']; ?>"></div><div><label>Curso específico</label><select name="id_curso"><option value="">No aplica</option><?php foreach($cursos as $c): ?><option value="<?php echo (int)$c['id_curso']; ?>" <?php echo (int)$logro['id_curso']===(int)$c['id_curso']?'selected':''; ?>><?php echo learningH($c['titulo']); ?></option><?php endforeach; ?></select></div><div class="learning-check-field"><label><input type="checkbox" name="estado" value="1" <?php echo $logro['estado']?'checked':''; ?>> Logro activo</label></div><div class="learning-field-span"><button class="btn-crear">Guardar cambios</button></div></form></section></div></body></html>
